/** @param {NS} ns */
export async function main(ns) {
  const servers = ['n00dles', 'sigma-cosmetics', 'joesguns', 'hong-fang-tea', 'zer0', 'CSEC', 'avmnite-02h', 'Icarus'];

  // Gain root access on all servers
  for (const server of servers) {
    if (!ns.hasRootAccess(server)) {
      ns.nuke(server);
    }
  }

  // Main hacking loop
  while (true) {
    // Find weakest server by min security
    let targetServer = servers[0];
    let minSecurity = ns.getServerSecurityLevel(targetServer);

    for (const server of servers) {
      const sec = ns.getServerSecurityLevel(server);
      if (sec < minSecurity) {
        minSecurity = sec;
        targetServer = server;
      }
    }

    const minSecThreshold = ns.getServerMinSecurityLevel(targetServer);
    const maxMoney = ns.getServerMaxMoney(targetServer);
    const currentMoney = ns.getServerMoneyAvailable(targetServer);
    const currentSec = ns.getServerSecurityLevel(targetServer);

    // Weaken if security is above minimum
    if (currentSec > minSecThreshold) {
      await ns.weaken(targetServer);
    }
    // Grow if money is below max
    else if (currentMoney < maxMoney) {
      await ns.grow(targetServer);
    }
    // Hack if conditions are optimal
    else {
      await ns.hack(targetServer);
    }
  }
}

